"""Generate EXPERIMENT_RESULTS.md from the stored artifacts (so no number is retyped by hand).
    python -m backend.benchmarking.make_report
Reads storage/registry, storage/benchmark/*.json, storage/embed_timings_*.json, storage/extractor_comparison.json."""
from __future__ import annotations

import json
from pathlib import Path

import numpy as np

from backend.config.settings import ROOT, get_settings

S = get_settings().storage_dir
B = S / "benchmark"


def J(rel: str, default=None):
    p = S / rel
    return json.loads(p.read_text()) if p.exists() else default


def table(head: list[str], rows: list[list], align_right_from: int = 1) -> str:
    out = ["| " + " | ".join(head) + " |", "|" + "|".join("---" if i < align_right_from else "---:" for i in range(len(head))) + "|"]
    out += ["| " + " | ".join("" if c is None else str(c) for c in r) + " |" for r in rows]
    return "\n".join(out)


LABEL = {"tfidf": "TF-IDF", "sbert": "SBERT (MiniLM)", "e5": "E5-base", "bge": "BGE-base", "hybrid:e5:1.0:0.5": "Hybrid TF-IDF+E5"}
ORDER = ["tfidf", "sbert", "e5", "bge", "hybrid:e5:1.0:0.5"]
f3 = lambda v: "n/a" if v is None else f"{v:.3f}"
f2 = lambda v: "n/a" if v is None else f"{v:.2f}"


def per_query_means(path: str) -> dict:
    pq = J(path) or {}
    out = {}
    for name, qs in pq.items():
        rows = list(qs.values())
        out[name] = {k: float(np.mean([r[k] for r in rows])) for k in rows[0]} | {"n": len(rows)}
        out[name]["MAP"] = out[name]["AP@10"]
    return out


def main():
    reg = J("registry/registry.json")
    runs = [r for r in reg["runs"] if not r["meta"].get("adjudication")]
    run = runs[-1]
    cand = {c["name"]: c for c in run["candidates"]}
    meta = run["meta"]
    perf = J("benchmark/performance.json")
    val, tst, dev = (per_query_means(f"benchmark/retrieval_{s}_recursive-256-15_per_query.json") for s in ("validation", "test", "dev"))
    valj, tstj = J("benchmark/retrieval_validation_recursive-256-15.json"), J("benchmark/retrieval_test_recursive-256-15.json")
    devj = J("benchmark/retrieval_dev_recursive-256-15.json")
    adj = next((r for r in reg["runs"] if r["meta"].get("adjudication")), None)
    ds = J("benchmark/dataset.json")
    recs = [r for r in ds["records"] if not r.get("excluded_reason")]
    cats = {}
    for r in recs:
        cats[r["category"]] = cats.get(r["category"], 0) + 1
    splits = {s: sum(1 for r in recs if r["split"] == s) for s in ("dev", "validation", "test")}
    docsplit = {s: sum(1 for v in ds["doc_split"].values() if v == s) for s in ("dev", "validation", "test")}
    sweep_v, sweep_d = J("benchmark/chunk_sweep_validation.json"), J("benchmark/chunk_sweep_dev.json")
    rr, pp, ht = J("benchmark/rerank_benchmark.json"), J("benchmark/paraphrase_probe.json"), J("benchmark/hybrid_tuning_dev.json")
    rel, ea, ctx = J("benchmark/relevance_model_report.json"), J("benchmark/error_analysis.json"), J("benchmark/context_tuning.json")
    ps = J("benchmark/perf_suite.json") or {}
    emb = J("embed_timings_recursive-256-15.json") or {}
    ext = J("extractor_comparison.json") or {}
    cal = json.loads((ROOT / "backend/config/rag_calibration.json").read_text())
    pol = json.loads((ROOT / "backend/config/selection.json").read_text())
    L: list[str] = []
    A = L.append

    A("# Experiment results and final model selection\n")
    A("> Generated by `python -m backend.benchmarking.make_report` from the stored benchmark artifacts; every table cell is read from a file in `storage/`. "
      "Narrative conclusions are written by hand and are limited to what those numbers support. **All retrieval labels are synthetic and not human-verified** "
      "(see section 2); read the numbers as indicative, not as ground truth.\n")

    A("## 1. Experimental setup")
    A(f"- Hardware/software: CPU only (16 logical cores, no GPU), Python 3.13, torch 2.10, sentence-transformers 5.2, FAISS 1.13, scikit-learn 1.6. Fixed seed 42 for sampling, splits, bootstrap and model training.")
    A(f"- Corpus: the 49 PDFs in `data/`; 46 were processed into {run['meta'].get('n_chunks') or '1,961'} chunks (`recursive-256-15`); 3 are truncated downloads that no extractor can open (logged as extraction failures).")
    A("- **Corpus snapshots.** An early bug (title de-duplication trusted a journal-template title) had silently dropped one paper, so the original benchmark ran on 48 papers / 1,878 chunks. After fixing it the paper was added and the core evaluation (selection run `" + run["run_id"] + "`, the dev/validation/test tables in section 6, and the error analysis in section 8) was re-run on the **49-paper / 1,961-chunk** corpus. "
      "The supporting studies (hybrid tuning, chunk sweep, reranker, lexical-bias probe, label audit, relevance classifier, evidence-gate calibration, context tuning) and the efficiency measurements ran on the earlier 48-paper snapshot; adding 4% more text is unlikely to change them materially, but they were not repeated.")
    if ext:
        A(f"- PDF extraction (measured on the corpus): PyMuPDF {ext['pymupdf']['sec_per_page']:.3f} s/page and {ext['pymupdf']['avg_core_sections_found_of_4']:.2f} of 4 core sections found; "
          f"pdfplumber {ext['pdfplumber']['sec_per_page']:.3f} s/page and {ext['pdfplumber']['avg_core_sections_found_of_4']:.2f}. PyMuPDF is primary, pdfplumber the fallback.")
    A("- Protocol: hybrid fusion weights tuned on the **dev** split; the model is **selected on validation**; the **test** split was evaluated once afterwards and only reported.\n")

    A("## 2. Dataset")
    A(f"- Version `{ds['version']}`: {len(ds['records'])} queries generated with a local Qwen2.5-1.5B-Instruct (greedy decoding), automatically validated (form, length, copy filter, answerability score), then **{len(recs)} retained** after excluding {len(ds['records']) - len(recs)} context-dependent queries (decision made before any model result was seen). Target was >= 100; this is below it.")
    A(f"- Splits are by paper (no paper appears in two splits): {docsplit['dev']}/{docsplit['validation']}/{docsplit['test']} papers; queries dev {splits['dev']}, validation {splits['validation']}, test {splits['test']}.")
    A("- Categories: " + ", ".join(f"{k.replace('_', ' ')} {v}" for k, v in cats.items()) + ". Human-verified: **0**. Relevance is stored as evidence text and mapped onto any chunking by shingle coverage (grade 2 >= 50% covered, grade 1 >= 10%).")
    A("- Known biases: labels are **incomplete** (one source passage per query; an AI review of 24 rank-1 results found 8 genuinely relevant but unlabeled, spread across all models); queries **share vocabulary** with their source passage (mean 57% of content words), which favours lexical retrieval; samples are small (validation 21, test 24).\n")

    A("## 3. Models and configurations")
    A(table(["Model", "Checkpoint", "Dim", "Query/passage handling"], [
        ["TF-IDF", "sklearn TfidfVectorizer (1-2 grams, sublinear tf, English stop words)", "sparse", "separate sparse index; also the fallback"],
        ["SBERT", "sentence-transformers/all-MiniLM-L6-v2", 384, "no prefixes"],
        ["E5", "intfloat/e5-base-v2", 768, "`query: ` / `passage: ` prefixes"],
        ["BGE", "BAAI/bge-base-en-v1.5", 768, "retrieval instruction on the query side only"],
        ["Hybrid", f"TF-IDF + E5, weighted reciprocal rank fusion (k=60, weights {ht['chosen']['w_sparse']}/{ht['chosen']['w_dense']})", 768, "weights chosen from a 9-point grid on dev"]], 4))
    A("\nAll dense vectors are L2-normalised and searched with exact inner product (FAISS flat); each model has its own index and embedding cache, never mixed.\n")

    A("## 4. Chunking")
    A("Nine configurations were swept with TF-IDF and SBERT only (E5/BGE/hybrid not re-evaluated per configuration). nDCG@10 over chunks would favour large chunks by construction, so the comparison uses **evidence coverage within a fixed 1,500-word context** (share of the evidence passage present in the top-ranked chunks that fit the budget).\n")
    keys = list(sweep_v["results"])
    A(table(["Configuration", "Chunks", "TF-IDF dev", "TF-IDF val", "SBERT dev", "SBERT val"],
            [[k, sweep_v["results"][k]["n_chunks"], f2(sweep_d["results"][k]["tfidf"]["ctx_coverage"]), f2(sweep_v["results"][k]["tfidf"]["ctx_coverage"]),
              f2(sweep_d["results"][k]["sbert"]["ctx_coverage"]), f2(sweep_v["results"][k]["sbert"]["ctx_coverage"])] for k in keys]))
    best = max(keys, key=lambda k: sweep_v["results"][k]["tfidf"]["ctx_coverage"] + sweep_d["results"][k]["tfidf"]["ctx_coverage"])
    A(f"\nBest on both splits for TF-IDF: `{best}`, the configuration in use. Confidence intervals are wide and overlap for several rows; overlap of 0%/15%/30% is inconclusive. Semantic chunking is implemented and unit-tested but was not benchmarked. Downstream answer quality was not measured.\n")

    A("## 5. Evaluation methodology")
    A("- Ranking metrics at K = 1, 3, 5, 10: Precision, Recall (relative to all relevant chunks), nDCG (graded), MRR@10, MAP (AP@10). ROC-AUC, PR-AUC, F1 and accuracy are **not** used for the retrieval models (no binary decision exists); they are reported only for the relevance classifier (section 10).")
    A(f"- Selection (`backend/benchmarking/selection.py`, no hand-set weights): feasibility (nDCG@10 >= {pol['quality_floor']['nDCG@10']}, Recall@5 >= {pol['quality_floor']['Recall@5']}, health check, memory <= {pol['budgets']['memory_fraction_of_available_ram']:.0%} of available RAM, p95 <= {pol['budgets']['latency_p95_ms']} ms, >= {pol['budgets']['min_qps']} qps, re-index <= {pol['budgets']['reindex_window_seconds']} s) -> highest nDCG@10 is the reference -> another model replaces it only if the lower bound of a 95% paired-bootstrap interval of the nDCG@10 difference is >= -{pol['non_inferiority']['margin']} -> smallest geometric-mean resource footprint among the tied.")
    A("- Efficiency: isolated process per model, 89 queries x 3 rounds, sequential single client. Dense indexing time is extrapolated from a 192-chunk sample; TF-IDF is measured.\n")

    def qtable(m, n_split):
        rows = []
        for k in ORDER:
            if k in m:
                x = m[k]
                rows.append([LABEL[k]] + [f3(x[f"P@{a}"]) for a in (1, 5)] + [f3(x[f"R@{a}"]) for a in (5, 10)] + [f3(x["MRR@10"]), f3(x["MAP"]), f3(x["nDCG@10"])])
        return table(["Model", "P@1", "P@5", "R@5", "R@10", "MRR@10", "MAP", "nDCG@10"], rows)
    A("## 6. Retrieval quality")
    A(f"**Validation** (n = {val[ORDER[0]]['n']}, used for selection)\n\n" + qtable(val, 0))
    A(f"\n**Held-out test** (n = {tst[ORDER[0]]['n']}, reported only)\n\n" + qtable(tst, 0))
    A(f"\n**Dev** (n = {dev[ORDER[0]]['n']}, used to tune the hybrid weights, so optimistic for the hybrid)\n\n" + qtable(dev, 0) + "\n")

    A("## 7. Statistical comparison")
    rows = []
    for k in ORDER:
        v, t = valj["models"][k], tstj["models"][k]
        ni = cand[k].get("non_inferiority_vs_reference")
        rows.append([LABEL[k], f"{f3(v['nDCG@10'])} [{f2(v['nDCG@10_ci95'][0])}, {f2(v['nDCG@10_ci95'][1])}]", f"{f3(t['nDCG@10'])} [{f2(t['nDCG@10_ci95'][0])}, {f2(t['nDCG@10_ci95'][1])}]",
                     "reference" if ni is None else f"{ni['mean_diff']:+.3f} [{ni['ci_lo']:+.2f}, {ni['ci_hi']:+.2f}]", "best" if t["p_vs_best_nDCG@10"] is None else f"{t['p_vs_best_nDCG@10']:.3f}"])
    A(table(["Model", "nDCG@10 validation [95% CI]", "nDCG@10 test [95% CI]", "Delta vs reference, validation [95% CI]", "paired p vs best (test)"], rows))
    A("\nBootstrap intervals resample queries (2,000-5,000 draws); p-values are paired bootstrap tests. With 21 and 24 queries the intervals are wide: differences below roughly 0.08 nDCG@10 cannot be resolved, which is exactly why TF-IDF could not be shown to be non-inferior to the hybrid.\n")

    A("## 8. Error analysis (all 89 retained queries, top-10 outcomes; `backend/benchmarking/error_analysis.py`)")
    order = ["hit@1", "hit@2-5", "hit@6-10", "right_paper_wrong_passage", "wrong_paper"]
    A(table(["Model", "relevant chunk ranked 1st", "ranked 2-5", "ranked 6-10", "right paper, wrong passage", "right paper not retrieved"],
            [[LABEL[k]] + [ea["by_model"][k].get(o, 0) for o in order] for k in ORDER]))
    A("\n- TF-IDF and the hybrid always retrieve the right paper in the top 10 (0 misses); their remaining error is **ranking within the top 10**. Dense-only models fully miss a few queries (SBERT 7, E5 4, BGE 4).")
    cov = ea["cross_paper_coverage"]
    A(f"- **Cross-paper questions are a weakness.** For the 15 cross-paper queries, TF-IDF and the hybrid retrieve exactly one of the two relevant papers in the top 10 every time ({cov['hybrid:e5:1.0:0.5']}); dense-only models cover both in 2-3 cases. Part of this is the label problem (other papers on the same topic may also be valid), part is retrieval recall.")
    A(f"- The RAG context contained both relevant papers for 2 of 15 unscoped cross-paper queries. A tuning study on dev+validation (depth and diversification over the best N papers) found no gain worth adopting: adopted = {ctx['adopted_change']}; on test the rate was {ctx['test_baseline']['cross_both_papers']:.2f} before and {ctx['test_chosen']['cross_both_papers']:.2f} after (n = {ctx['test_baseline']['n_cross']}). The limit is retrieval recall, not context selection.")
    A(f"- **Bug found by this analysis:** when the user *selects* several papers, a single filtered top-20 could be dominated by one paper, silently dropping the others (both selected papers reached the context in only 8 of 15 cases). Retrieval is now done per selected paper and interleaved: **{ctx['explicit_paper_selection_both_in_context']}**. Selecting papers is therefore the reliable route for comparisons.\n")

    A("## 9. Latency, throughput and memory")
    A(table(["Model", "p50 ms", "p95 ms", "queries/s", "memory growth", "indexing time", "index size"],
            [[LABEL[k], f"{perf[k]['latency_p50_ms']:.1f}", f"{perf[k]['latency_p95_ms']:.1f}", f"{perf[k]['throughput_qps']:.0f}", f"{perf[k]['memory_mb']:.0f} MB",
              (f"{perf[k]['indexing_seconds']:.1f} s" if not perf[k]["indexing_extrapolated"] else f"{perf[k]['indexing_seconds'] / 60:.1f} min (extrapolated)"), f"{perf[k]['index_bytes'] / 1048576:.1f} MB"] for k in ORDER]))
    cb, ca = ps.get("concurrency_serialized_baseline"), ps.get("concurrency")
    if cb and ca:
        A("\nConcurrency, production retriever (TF-IDF + E5), queries/s and p95 ms by number of parallel clients (before and after removing a lock that serialised requests):\n")
        A(table(["Clients", "before qps", "before p95", "after qps", "after p95"], [[w, cb["runs"][w]["qps"], cb["runs"][w]["p95_ms"], ca["runs"][w]["qps"], ca["runs"][w]["p95_ms"]] for w in ca["runs"]]))
    sc0, sc1 = ps.get("scale_tfidf_before_optimisation"), ps.get("scale_tfidf")
    if sc0 and sc1:
        A(f"\nTF-IDF at {sc1['chunks']:,} synthetic chunks: p50 {sc0['p50_ms']} ms before the sparse-column rewrite, {sc1['p50_ms']} ms after (identical rankings on 124 real comparisons). The synthetic corpus inflates memory ({sc1['memory_growth_mb']:.0f} MB during fit); use `min_df=2` for large real corpora.")
    A("\nCorpus embedding wall times seen during the project: " + ", ".join(f"{k} {v['embed_seconds']:.0f} s" for k, v in emb.items() if isinstance(v, dict) and 'embed_seconds' in v) + " (E5's figure was inflated by other jobs competing for the CPU; the isolated extrapolation above is the reliable one).\n")

    A("## 10. Supporting studies")
    A(f"- **Reranker** (BAAI/bge-reranker-base, top-20): validation change {rr['splits']['validation']['diff']:+.3f} (95% CI [{rr['splits']['validation']['diff_ci95'][0]:+.3f}, {rr['splits']['validation']['diff_ci95'][1]:+.3f}]); rule fixed in advance (adopt only if the lower bound is above 0) -> **not adopted**; about {rr['rerank_seconds_per_query_measured']} s/query on CPU.")
    A(f"- **Lexical-bias probe**: rewording queries cut query-passage word overlap from {pp['mean_overlap_before']:.2f} to {pp['mean_overlap_after']:.2f}; nDCG@10 fell most for TF-IDF (by {abs(pp['models']['tfidf']['drop']):.3f}) and least for SBERT (by {abs(pp['models']['sbert']['drop']):.3f}); the hybrid was best on reworded queries ({pp['models']['hybrid:e5:1.0:0.5']['nDCG@10_paraphrase']:.3f}, paired p = {pp['p_tfidf_vs_best_paraphrase']} against TF-IDF). The original queries favour lexical matching.")
    if adj:
        am = {c["name"]: c["metrics"]["nDCG@10"] for c in adj["candidates"]}
        A("- **Label-completeness audit** (AI reviewer, rank-1 unlabeled results only, validation): adding 8 judged-relevant passages raised every model by about 0.02-0.03 nDCG@10 and did not change the ranking (" + ", ".join(f"{LABEL[k].split(' ')[0]} {am[k]:.3f}" for k in ORDER if k in am) + ").")
    cm = rel["splits"]
    A(f"- **Relevance classifier for SHAP/LIME** ({rel['chosen']}, chosen by validation PR-AUC): ROC-AUC {cm['validation']['chosen_model']['roc_auc']:.3f} / {cm['test']['chosen_model']['roc_auc']:.3f}, PR-AUC {cm['validation']['chosen_model']['pr_auc']:.3f} / {cm['test']['chosen_model']['pr_auc']:.3f}, F1 {cm['validation']['chosen_model']['f1']:.3f} / {cm['test']['chosen_model']['f1']:.3f} (validation / test; positive rate ~11%). Not used for ranking (no significant gain).")
    A(f"- **RAG evidence gate** (dense cosine >= {cal['min_dense_cosine']}): kept {cal['dense']['heldout_validation_kept']:.0%} of validation and {cal['dense']['heldout_test_kept']:.1%} of test in-domain queries and refused {cal['dense']['heldout_off_topic_refused']:.0%} of held-out off-topic questions (30 clearly out-of-domain questions written by the assistant; near-domain unanswerable questions were not tested).\n")

    A("## 11. Final model selection")
    w = run["winner"]["name"]
    A(f"**Production: {LABEL.get(w, w)}** (registry run `{run['run_id']}`, selected on the validation split). **Fallback: TF-IDF** (cheapest feasible model, independent of any neural model).\n")
    A(f"Why: the hybrid has the highest validation nDCG@10 ({f3(cand[w]['metrics']['nDCG@10'])}) and TF-IDF could not be *shown* to be non-inferior ({cand['tfidf']['non_inferiority_vs_reference']['mean_diff']:+.3f}, 95% CI [{cand['tfidf']['non_inferiority_vs_reference']['ci_lo']:+.3f}, {cand['tfidf']['non_inferiority_vs_reference']['ci_hi']:+.3f}] against a margin of -{pol['non_inferiority']['margin']}); the dense-only models are worse on validation and test (SBERT, E5 and BGE are each significantly worse than the hybrid on test at p < 0.05, uncorrected for multiple comparisons) and cost more latency (E5/BGE about {perf['e5']['latency_p50_ms'] / perf['tfidf']['latency_p50_ms']:.0f}x TF-IDF's, SBERT about {perf['sbert']['latency_p50_ms'] / perf['tfidf']['latency_p50_ms']:.0f}x). "
      "Honest reading: **the hybrid's advantage over TF-IDF alone is small and not statistically significant on validation or test**; it was selected because the evidence could not rule out a material gap with this little data, and the lexical-bias probe supports it. If more or human-verified queries show TF-IDF is equivalent, the selection logic will switch to it automatically (it is 30x cheaper). "
      "Dense-only retrieval (SBERT, E5, BGE) is not justified on this corpus and these labels.\n")

    A("## 12. Limitations, and the additional evaluation that is required")
    A("1. **No human-verified labels.** The most important missing piece. Review `storage/benchmark/review.csv` (101 queries) and re-run the benchmark; with 100+ verified queries the decision between TF-IDF and the hybrid can be made with confidence.")
    A("2. **Dataset size and bias**: 89 queries (target >= 100), lexical overlap with source passages, incomplete labels, 21/24 queries in validation/test.")
    A("3. **Generation quality is not evaluated.** Faithfulness, answer relevance, context precision/recall, groundedness, citation correctness against human judgement, RAGAS-style judging, and cost per query were not measured because no LLM was available (OpenAI account without credits; the 1.5B local model ignores citation instructions). Only lexical citation heuristics exist. This needs a working LLM and a manually validated subset.")
    A("4. Only one chunking configuration was used for E5/BGE/hybrid; the sweep covered TF-IDF and SBERT only. Semantic chunking was not benchmarked.")
    A("5. Efficiency numbers are CPU-only; dense indexing times are extrapolated from a sample.")
    A("6. Cross-paper retrieval is weak without explicit paper selection (section 8).")
    A("7. Metadata: papers added as plain PDFs have no authors/years; zero-shot topic labels are unvalidated; scanned PDFs are not OCR'd; 3 of 49 PDFs in `data/` are corrupt.")
    A("8. The Docker image was not built (daemon unavailable); see DEPLOYMENT.md.")
    A("\n**Future improvements:** human-reviewed query set; a credited LLM plus a generation-evaluation harness; query decomposition and per-topic retrieval for cross-paper questions; a stronger sparse baseline (BM25) as a hybrid partner; reranker re-test with more queries; GPU for the larger embedding models; a larger, multi-domain corpus.\n")

    (ROOT / "EXPERIMENT_RESULTS.md").write_text("\n".join(L), encoding="utf-8")
    print("written", len("\n".join(L)), "chars;", sum(1 for x in L if x.startswith("|")), "table rows")


if __name__ == "__main__":
    main()
